1	/**
2	 * Apollo.io API wrapper — server-only.
3	 * Used by /api/lead to upsert contacts.
4	 *
5	 * Apollo docs: https://docs.apollo.io/reference
6	 */
7	
8	const APOLLO_BASE = "https://api.apollo.io/api/v1";
9	
10	interface ApolloContactInput {
11	  email: string;
12	  first_name?: string;
13	  last_name?: string;
14	  organization_name?: string;
15	  title?: string;
16	  phone?: string;
17	  // Apollo allows arbitrary labels (lead source, UTMs, etc.)
18	  label_names?: string[];
19	}
20	
21	interface ApolloApiResult {
22	  ok: boolean;
23	  contact_id?: string;
24	  raw?: unknown;
25	  error?: string;
26	}
27	
28	function apolloKey(): string {
29	  const k = process.env.APOLLO_API_KEY;
30	  if (!k) throw new Error("APOLLO_API_KEY missing");
31	  return k;
32	}
33	
34	/**
35	 * Upsert (search-then-create-or-update) an Apollo contact.
36	 * Returns the Apollo contact id so it can be stored on the Supabase lead row.
37	 */
38	export async function upsertApolloContact(input: ApolloContactInput): Promise<ApolloApiResult> {
39	  try {
40	    const splitName = (input.first_name || input.last_name)
41	      ? { first_name: input.first_name, last_name: input.last_name }
42	      : splitDisplayName(undefined);
43	
44	    const body = {
45	      first_name: splitName.first_name ?? "",
46	      last_name: splitName.last_name ?? "",
47	      email: input.email,
48	      organization_name: input.organization_name,
49	      title: input.title,
50	      phone_numbers: input.phone ? [{ raw_number: input.phone }] : undefined,
51	      label_names: input.label_names
52	    };
53	
54	    const existing = await findApolloContactByEmail(input.email);
55	    if (existing?.id) {
56	      // Best-effort patch to avoid duplicate contacts when this email already exists.
57	      await patchApolloContact(existing.id, body);
58	      return { ok: true, contact_id: existing.id, raw: existing };
59	    }
60	
61	    const res = await apolloRequest("/contacts", "POST", body);
62	
63	    if (!res.ok) {
64	      const text = await res.text();
65	      return { ok: false, error: `Apollo upsert failed: ${res.status} ${text}` };
66	    }
67	
68	    const data = (await res.json()) as { contact?: { id?: string } };
69	    return { ok: true, contact_id: data.contact?.id, raw: data };
70	  } catch (err) {
71	    return { ok: false, error: err instanceof Error ? err.message : String(err) };
72	  }
73	}
74	
75	interface ApolloContactSearchResult {
76	  id?: string;
77	}
78	
79	async function findApolloContactByEmail(email: string): Promise<ApolloContactSearchResult | null> {
80	  const candidates = ["/contacts/search", "/mixed_people/search"];
